/**
 * Golden-fixture generator (run once; the emitted files are committed).
 *
 *   bun packages/attest/test/fixtures/gen-fixtures.ts
 *
 * Emits byte-faithful reproductions of the venture artifact formats using each
 * venture's EXACT construction (read from its source), so the committed fixtures
 * are what Duedale's `/report/report.json` and Indusland's IVFC1 issuer produce:
 *   • countersign-bundle.json  — a two-signature bundle: an ordinary DSSE envelope
 *                                the holder signed, countersigned by a second,
 *                                independent key over the SAME PAE bytes. Built
 *                                with attest + identity-core only — the same
 *                                path a stranger has — so `attest verify` on it
 *                                proves the artifact, not our tooling.
 *   • duedale-report.json      — signReport + computeChainSummary (ks-adapters/report)
 *   • indus-ivfc1.token.txt     — issue-footfall-certificate construction
 *   • indus-keys.json           — the platform JWKS for the IVFC1 signer
 *
 * (The Oreoasis bundle fixture is REAL venture output — generated by running the
 * Oreoasis repo's own `scripts/export-audit-bundle.ts` offline.)
 */

import { writeFileSync } from "node:fs";
import { join } from "node:path";
import {
  canonicalize,
  canonicalizeBytes,
  deriveDid,
  encodeHex,
  generateKeyPair,
  signEvent,
} from "@kashscript/identity-core";
import { base64ToBytes, bytesToBase64, bytesToBase64Url, signRaw } from "../../src/ed25519";
import { sha256Hex } from "../../src/chain";
import { pae, signEnvelope } from "../../src/dsse";
import {
  COUNTERSIGN_BUNDLE_FORMAT,
  DST_COUNTERSIGN_ACCEPTANCE,
  DST_COUNTERSIGN_REQUEST,
  countersignRequestDigest,
} from "../../src/countersign";

const DIR = import.meta.dir;
const enc = new TextEncoder();
function concat(...parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((n, p) => n + p.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.length;
  }
  return out;
}

/* ── Duedale Every-Rupee report (ks-adapters/src/report/index.ts) ──────── */
async function genDuedaleReport(): Promise<void> {
  const op = await generateKeyPair();
  const REPORT_DST = "kash-report-v1\n";
  const GENESIS = "duedale-every-rupee-chain-v1";

  const chainRows = [
    { grantId: "grant_001", toState: "ISSUED", actorDid: "did:kash:funder:demo", actorClass: "FUNDER", reason: "grant issued", code: null, atUnix: 1_700_000_000 },
    { grantId: "grant_001", toState: "REDEEMED", actorDid: "did:kash:vendor:demo", actorClass: "VENDOR", reason: "voucher redeemed at approved vendor", code: null, atUnix: 1_700_003_600 },
  ];
  // rowHash_i = SHA-256( utf8(prevHex) ‖ JCS(row) ), genesis prev = SHA-256(utf8(GENESIS))
  const links: Array<{ seq: number; row: unknown; rowHashHex: string; prevHashHex: string }> = [];
  let prev = await sha256Hex(enc.encode(GENESIS));
  let seq = 0;
  for (const row of chainRows) {
    const rowHash = await sha256Hex(concat(enc.encode(prev), canonicalizeBytes(row)));
    links.push({ seq, row, rowHashHex: rowHash, prevHashHex: prev });
    prev = rowHash;
    seq += 1;
  }

  const report = {
    meta: { reportId: "report_demo_1700010000", programId: "prog_demo", programName: "Demo Program", funderDid: "did:kash:funder:demo", generatedAtUnix: 1_700_010_000, simulation: true, anomalies: 0, disclaimers: ["SIMULATION — figures illustrate the format, not a real disbursement."] },
    grants: [{ grantId: "grant_001", purposeTag: "food", amountPaisa: 250000, state: "REDEEMED", issuedAtUnix: 1_700_000_000, deliveredAtUnix: 1_700_001_000, redeemedAtUnix: 1_700_003_600, redeemedByVendorDid: "did:kash:vendor:demo", expiryUnix: 1_800_000_000, signatureValid: true }],
    vendors: [{ vendorDid: "did:kash:vendor:demo", redeemedCount: 1, redeemedPaisa: 250000 }],
    totals: { issuedCount: 1, issuedPaisa: 250000, redeemedCount: 1, redeemedPaisa: 250000, expiredCount: 0, unspentPaisa: 0, settledPaisa: 0, refundedPaisa: 0 },
    chain: { algorithm: "sha256-jcs-linked", genesisLabel: GENESIS, transitionCount: links.length, headHashHex: links.length === 0 ? null : links[links.length - 1]!.rowHashHex, computedAtRender: true, durablyAnchored: false, links },
  };

  const header = { typ: "duedale/every-rupee-report", v: 1, reportId: report.meta.reportId };
  const signature = await signEvent(header, report, op.privateKey, { dst: REPORT_DST });
  const signed = {
    report,
    signature,
    operatorPublicKeyHex: encodeHex(op.publicKey),
    verify: { spec: "RFC 8785 (JCS) + Ed25519", dst: REPORT_DST, steps: ["verify with: attest verify duedale-report.json"] },
  };
  writeFileSync(join(DIR, "duedale-report.json"), JSON.stringify(signed, null, 2) + "\n");
  console.log(`wrote duedale-report.json (operator ${encodeHex(op.publicKey).slice(0, 16)}…, ${links.length} links)`);
}

/* ── Indus IVFC1 (issue-footfall-certificate/index.ts) ─────────────────── */
async function genIndusIvfc1(): Promise<void> {
  const kp = await generateKeyPair();
  const DST = "indus.vfc.v1.cert";
  const PLATFORM_KID = "indus.platform.vfc.v1";
  const org = "11111111-1111-1111-1111-111111111111";
  const label = "2026-05";

  const certPre = enc.encode(`indus.vfc.v1:${org}:${label}`);
  const certDigest = new Uint8Array(await crypto.subtle.digest("SHA-256", certPre as unknown as BufferSource));
  const certId = bytesToBase64Url(certDigest.slice(0, 16));
  const iat = 1_717_200_000;

  const header = { alg: "EdDSA", kid: PLATFORM_KID, v: 1, typ: "IVFC1" };
  const body = {
    typ: "IVFC1",
    iss: "indus.platform",
    certId,
    org,
    orgName: "Demo Org",
    period: { start: `${label}-01T00:00:00+05:00`, end: "2026-06-01T00:00:00+05:00", label },
    k: 5,
    totals: { verifiedTravelers: 42, verifiedScans: 128, repeatVisitors: 9, venues: 3, byHour: null },
    venues: [{ venueId: "venue-1", suppressed: false, verifiedTravelers: 42, verifiedScans: 128, repeatVisitors: 9 }],
    methodology:
      "IPOE1 attested QR scans, Ed25519-verified server-side; PII-free aggregates; " +
      "minors and deleted users excluded; venues with fewer than 5 distinct verified " +
      "travellers are suppressed; hours are Asia/Karachi local.",
    iat,
  };

  const headerB64u = bytesToBase64Url(enc.encode(JSON.stringify(header)));
  const bodyB64u = bytesToBase64Url(enc.encode(canonicalize(body)));
  const signingInput = concat(enc.encode(DST), new Uint8Array([0]), enc.encode(headerB64u), enc.encode("."), enc.encode(bodyB64u));
  const sig = await signRaw(signingInput, kp.privateKey, kp.publicKey);
  const token = `IVFC1.${headerB64u}.${bodyB64u}.${bytesToBase64Url(sig)}`;

  writeFileSync(join(DIR, "indus-ivfc1.token.txt"), token + "\n");
  const jwks = { keys: [{ kty: "OKP", crv: "Ed25519", x: bytesToBase64Url(kp.publicKey), kid: PLATFORM_KID, use: "sig", alg: "EdDSA" }] };
  writeFileSync(join(DIR, "indus-keys.json"), JSON.stringify(jwks, null, 2) + "\n");
  console.log(`wrote indus-ivfc1.token.txt + indus-keys.json (kid ${PLATFORM_KID})`);
}

/* ── Countersign bundle — the mechanic of ECOSYSTEM decision 26 ─────────── */
async function genCountersignBundle(): Promise<void> {
  const holder = await generateKeyPair();
  const counterparty = await generateKeyPair();
  const holderDid = deriveDid(holder.publicKey);
  // The counterparty's key is one-time and belongs to this relationship only —
  // a second requester would see a different DID entirely (d41).
  const counterpartyDid = deriveDid(counterparty.publicKey);
  const issuedAtUnix = 1_700_000_000;
  const signedAtUnix = issuedAtUnix + 3_600;
  const PAYLOAD_TYPE = "application/vnd.example.delivery+json";

  // 1. The holder signs something ordinary. No new format, no new DST.
  const subject = await signEnvelope(
    { orderRef: "A-77", deliveredAtUnix: issuedAtUnix - 600, items: 3 },
    PAYLOAD_TYPE,
    { keyid: holderDid, privateKey: holder.privateKey, publicKey: holder.publicKey },
    { canonical: true },
  );
  const subjectBytes = base64ToBytes(subject.payload);
  const subjectDigestSha256 = await sha256Hex(subjectBytes);

  // 2. The request — addressed by capability, naming no counterparty.
  const requestBody = {
    requestId: "csr_1f4c9a2b7e6d05834ac1b9e27d6f3a55",
    requesterDid: holderDid,
    subjectPayloadType: PAYLOAD_TYPE,
    subjectDigestSha256,
    statement: "Confirm you received the delivery for order A-77.",
    disclosures: [
      { label: "Order", value: "A-77" },
      { label: "Items", value: "3" },
    ],
    nonceB64: bytesToBase64(new Uint8Array(32).fill(0x5a)),
    issuedAtUnix,
    expiresAtUnix: issuedAtUnix + 14 * 24 * 60 * 60,
    relationshipContext: "book-demo",
    withdrawalFeed: null,
  };
  const requestHeader = { typ: "countersign-request", v: 1 };
  const request = {
    header: requestHeader,
    body: requestBody,
    signature: await signEvent(requestHeader, requestBody, holder.privateKey, {
      dst: DST_COUNTERSIGN_REQUEST,
    }),
  };

  // 3. One click: the same PAE bytes signed by a second key, plus the
  //    acceptance that carries the time, the binding and the key's custody.
  const countersignature = await signRaw(
    pae(PAYLOAD_TYPE, subjectBytes),
    counterparty.privateKey,
    counterparty.publicKey,
  );
  const envelope = {
    ...subject,
    signatures: [...subject.signatures, { keyid: counterpartyDid, sig: bytesToBase64(countersignature) }],
  };
  const acceptanceBody = {
    act: "countersign" as const,
    requestId: requestBody.requestId,
    requestDigestSha256: await countersignRequestDigest(request),
    subjectPayloadType: PAYLOAD_TYPE,
    subjectDigestSha256,
    countersignerDid: counterpartyDid,
    keyCustody: "subject-generated" as const,
    signedAtUnix,
  };
  const acceptanceHeader = { typ: "countersign", v: 1 };
  const bundle = {
    formatVersion: COUNTERSIGN_BUNDLE_FORMAT,
    subject: envelope,
    request,
    acceptances: [
      {
        header: acceptanceHeader,
        body: acceptanceBody,
        signature: await signEvent(acceptanceHeader, acceptanceBody, counterparty.privateKey, {
          dst: DST_COUNTERSIGN_ACCEPTANCE,
        }),
      },
    ],
    withdrawal: null,
    verify: {
      spec: "DSSE/PAE (two signatures over identical bytes) + RFC 8785 JCS Kash-Events",
      steps: ["verify with: attest verify countersign-bundle.json  (no --key: the DIDs carry the keys)"],
    },
  };

  writeFileSync(join(DIR, "countersign-bundle.json"), JSON.stringify(bundle, null, 2) + "\n");
  console.log(`wrote countersign-bundle.json (holder ${holderDid.slice(0, 22)}…, counterparty ${counterpartyDid.slice(0, 22)}…)`);
}

await genCountersignBundle();
await genDuedaleReport();
await genIndusIvfc1();
console.log("fixtures generated.");
